import 'package:flutter/material.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'firebase_options.dart';
import 'widgets/ui.dart';
import 'screens/auth_screen.dart';
import 'screens/home_screen.dart';

Future<void> main()async{
  WidgetsFlutterBinding.ensureInitialized();
  // Android google-services.json / iOS GoogleService-Info.plist are generated by
  // flutterfire configure. See README.md; never embed service-account credentials.
  try {
    await Firebase.initializeApp(
      options: DefaultFirebaseOptions.currentPlatform,
    );
    runApp(const TutorTrackApp());
  }catch(error){runApp(MaterialApp(home:Scaffold(body:Center(child:Padding(
    padding:const EdgeInsets.all(28),child:Column(mainAxisSize:MainAxisSize.min,children:[
      const Icon(Icons.cloud_off_rounded,size:52,color:forest),const SizedBox(height:18),
      const Text('Firebase setup is required',style:TextStyle(fontSize:22,fontWeight:FontWeight.w700)),
      const SizedBox(height:12),const Text('Run flutterfire configure for Android and iOS, then rebuild the app.',textAlign:TextAlign.center),
      const SizedBox(height:12),Text('$error',style:const TextStyle(fontSize:11,color:muted)),
    ]))))));}
}

class TutorTrackApp extends StatelessWidget{
  const TutorTrackApp({super.key});
  @override Widget build(BuildContext context)=>MaterialApp(
    title:'TutorTrack',theme:tutorTheme(),debugShowCheckedModeBanner:false,
    home:StreamBuilder<User?>(stream:FirebaseAuth.instance.authStateChanges(),
      builder:(context,snapshot){
        if(snapshot.connectionState==ConnectionState.waiting)return const Scaffold(body:Center(child:CircularProgressIndicator()));
        return snapshot.data==null?const AuthScreen():HomeScreen(key:ValueKey(snapshot.data!.uid));
      }),
  );
}
